// Regenerates src/data/warbands/index.ts from the JSON files in that folder.
import { readdirSync, writeFileSync } from 'node:fs';
const dir = new URL('../src/data/warbands/', import.meta.url);
const files = readdirSync(dir).filter((f) => f.endsWith('.json')).sort();
const ident = (f) => 'w_' + f.replace(/\.json$/, '').replace(/[^a-z0-9]/gi, '_');
const out = [
  '// Generated by scripts/gen-index.mjs; do not edit.',
  "import type { WarbandDef } from '../../types';",
  ...files.map((f) => `import ${ident(f)} from './${f}';`),
  '',
  `export const ALL_WARBANDS = [${files.map(ident).join(', ')}] as unknown as WarbandDef[];`,
  '',
].join('\n');
writeFileSync(new URL('index.ts', dir), out);
console.log(`warbands index: ${files.length} files`);
